container_contract.original_compose:
services:
  authelia:
    entrypoint:
    - /bin/sh
    - /usr/local/bin/proxmenux-authelia-bootstrap
    environment:
      AUTHELIA_IDENTITY_VALIDATION_RESET_PASSWORD_JWT_SECRET: ${GENERATED_RESET_PASSWORD_JWT_SECRET}
      AUTHELIA_SESSION_SECRET: ${GENERATED_SESSION_SECRET}
      AUTHELIA_STORAGE_ENCRYPTION_KEY: ${GENERATED_STORAGE_ENCRYPTION_KEY}
      PROXMENUX_ADMIN_PASSWORD: ${GENERATED_ADMIN_PASSWORD}
      PROXMENUX_AUTHELIA_COOKIE_DOMAIN: ${AUTHELIA_COOKIE_DOMAIN}
      PROXMENUX_AUTHELIA_URL: ${AUTHELIA_URL}
      X_AUTHELIA_CONFIG_FILTERS: template
    image: docker.io/authelia/authelia:4.39.28
    ports:
    - 9091:9091
    restart: unless-stopped
    volumes:
    - ./authelia:/config
